import {Mode} from './mode-base.js';
import {ampeMotion,AMPE_DURATION} from './ampe-motion.js';
export class Ampe extends Mode{
 constructor(ctx){super(ctx);this.world.setCamera([0,3.6,6.8,0,1,0]);this.you=this.player(-.85,0,this.settings.color,{gender:'female'});this.other=this.player(.85,0,0x348b79,{gender:'female'});this.you.rotation.y=Math.PI/2;this.other.rotation.y=-Math.PI/2;this.circle(0,0,2.6);this.scores=[0,0];this.phase='choose';this.round=0;this.choice=0;this.rivalChoice=0;this.claps=0;this.choiceMade=false;this.poseAt(0);this.setActions([{id:'left',label:'Left foot',key:'Space'},{id:'right',label:'Right foot',key:'E'}]);this.note('You score matching feet; your rival scores opposite feet. Choose a foot, clap together, jump and land together. First to five.');}
 action(id){if(this.onlineSend){if(this.phase==='choose'&&!this.choiceMade&&['left','right'].includes(id)){this.choiceMade=true;this.onlineSend(id==='left'?0:1);this.note('Foot locked. Waiting for your friend…');}return;}if(this.phase!=='choose'||!['left','right'].includes(id))return;this.choice=id==='right'?1:0;this.rivalChoice=Math.random()<.5?0:1;this.phase='sequence';this.time=0;this.claps=0;}
 poseAt(t){for(const [i,p]of [this.you,this.other].entries()){const foot=i?this.rivalChoice:this.choice,m=ampeMotion(t,foot);p.userData.ampeTime=t;p.userData.ampeFoot=foot;p.userData.ampeExtend=m.extend;p.userData.ampeCrouch=m.crouch;p.userData.jump=m.jump;p.userData.pose='ampe';}}
 update(dt){this.status(`YOU ${this.scores[0]} — ${this.scores[1]} ${this.opponentName||'THEM'}`,this.phase==='choose'?(this.choiceMade?'WAITING FOR YOUR FRIEND':'CHOOSE YOUR FOOT · FIRST TO 5'):'CLAP · JUMP · REVEAL');if(this.phase==='choose'){this.poseAt(0);return;}if(this.phase==='sequence'){this.poseAt(this.time);for(const [i,at]of [.24,.72].entries())if(this.time>=at&&this.claps<=i){this.claps=i+1;this.ui.sound('clap');}if(this.time>=1.64&&!this.scored){this.scored=true;if(!this.onlineSend)this.scores[this.choice===this.rivalChoice?0:1]++;this.note(this.choice===this.rivalChoice?'Same feet. The matching-foot player scores.':'Opposite feet. The opposite-foot player scores.');this.ui.sound('point');}if(this.time>=AMPE_DURATION&&!this.onlineSend){if(Math.max(...this.scores)>=5){this.score=this.scores[0];this.finish(this.score>=5?'AMPE CHAMPION!':'THEY HAVE THE RHYTHM',`${this.scores[0]} – ${this.scores[1]}`,this.score>=5);}else{this.phase='choose';this.round++;this.scored=false;this.note('Choose your next foot. Keep the rhythm.');}}}}
 syncOnline(state,slot,names){this.opponentName=names[1-slot];this.scores=[state.scores[slot],state.scores[1-slot]];this.choiceMade=!!state.locked?.[slot];if(state.phase==='reveal'){if(this.networkRound!==state.round){this.networkRound=state.round;this.choice=state.feet[slot];this.rivalChoice=state.feet[1-slot];this.phase='sequence';this.time=0;this.claps=0;this.scored=false;}}else if(state.phase==='choose'){this.phase='choose';this.scored=false;this.poseAt(0);}this.status(`YOU ${this.scores[0]} — ${this.scores[1]} ${this.opponentName}`,slot===0?'YOU SCORE MATCHING FEET':'YOU SCORE OPPOSITE FEET');}
}
